import{escapeHtml}from"escape-goat";function post(){const b=http.body;if(!b.account_id||!b.amount||!b.no){json.fail(400,"account_id, amount, no required");return;}const no=escapeHtml(String(b.no));db.exec("insert into orders (no, account_id, amount) values (?, ?, ?)",[no,b.account_id,b.amount]).then(()=>json.ok({created:true,no})).catch(e=>json.fail(500,String(e)));}function get(){const id=Number(http.param("id",0));db.query("select id, no, account_id, amount from orders where account_id = ?",[id]).then(r=>json.ok(r)).catch(e=>json.fail(500,String(e)));}export default{get,post};